try:
    print('>>> f = hasattr')
    print('>>> x = 3')
    print('>>> y = b""')
    print('>>> f(x, y)')
    f = hasattr
    x = 3
    y = b""
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
